const b=$input.first().json.body||{};
const S=v=>v==null?'':String(v).trim();
const num=v=>{const n=parseFloat(String(v==null?'':v).replace(/[^0-9.-]/g,''));return isNaN(n)?0:n;};
const f3=n=>String(Math.round(n*1000)/1000);
const H='https://old-hub.example/webhook/',K='[redacted-internal-key]';
const NL=String.fromCharCode(10);
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
const stamp=now.slice(8,10)+'/'+now.slice(5,7)+'/'+now.slice(0,4)+' '+now.slice(11,16);
const by=S(b.by).slice(0,80);
if(!by) return [{json:{ok:false,kind:'err',message:'Choose your name at the top first.'}}];
const notify=async(o)=>{try{await this.helpers.httpRequest({method:'POST',url:H+'cbs-notify',body:o,json:true,timeout:15000});}catch(e){}};
if(b.action==='plant'){
  const R=await this.helpers.httpRequest({method:'GET',url:H+'cbs-admin-data?t=assets',json:true,timeout:30000});
  const a=(R.assets||[]).find(x=>String(x.id)===S(b.id));
  if(!a) return [{json:{ok:false,kind:'err',message:'That item was not found. Refresh and try again.'}}];
  const flag=S(b.flag),note=S(b.note).slice(0,500);let ch={},msg='',ev='',label='';
  if(flag==='faulty'){if(!note)return [{json:{ok:false,kind:'err',message:'Add a note saying what is wrong.'}}];ch.status='Needs repair';label='Faulty';ev='plant_faulty';
    msg=a.name+(a.asset_tag?' ('+a.asset_tag+')':'')+' reported faulty by '+by+': '+note;}
  else if(flag==='missing'){if(!note)return [{json:{ok:false,kind:'err',message:'Add a note saying where it was last seen.'}}];ch.status='Lost';label='Missing';ev='plant_missing';
    msg=a.name+(a.asset_tag?' ('+a.asset_tag+')':'')+' reported missing by '+by+'. Last recorded at '+(S(a.location)||'unknown')+'. '+note;}
  else if(flag==='found'){const loc=S(b.location)||S(a.location)||'CBS Warehouse';ch.status='In service';ch.location=loc;label=a.status==='Needs repair'?'Back in use':'Found';ev='plant_found';
    msg=a.name+(a.asset_tag?' ('+a.asset_tag+')':'')+(a.status==='Needs repair'?' marked back in use':' found')+' by '+by+', now at '+loc+'.'+(note?' '+note:'');}
  else return [{json:{ok:false,kind:'err',message:'Choose what has happened.'}}];
  ch.notes=(S(a.notes)?S(a.notes)+NL:'')+stamp+' '+label+' ('+by+', Yard page)'+(note?': '+note:'');
  await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=assets&id='+a.id+'&partial=1',body:ch,json:true,timeout:20000});
  await notify({event:ev,job_no:'',message:msg,link:H+'cbs-admin?open=assets'});
  return [{json:{ok:true,kind:'plant',message:a.name+': '+label.toLowerCase()+'. The office has been told.'}}];
}
if(b.action==='matreturn'){
  const q=num(b.qty);if(!(q>0)) return [{json:{ok:false,kind:'err',message:'Enter how much came back.'}}];
  const job=S(b.job).replace(/[^0-9A-Za-z-]/g,'');
  if(S(b.id)==='__other'){
    const nm=S(b.name).slice(0,120),un=S(b.unit).slice(0,30);if(!nm) return [{json:{ok:false,kind:'err',message:'Say what came back.'}}];
    await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=stockmoves',body:{material_id:'',material:nm,change:f3(q),qty_after:'',reason:'Returned from job (not in register)',ref:job?'Job '+job:'Yard return',by:by,at:now,notes:un?'Unit: '+un:'',location:'CBS Warehouse'},json:true,timeout:20000});
    await notify({event:'stock_return',job_no:'',message:by+' brought back '+f3(q)+(un?' '+un:'')+' '+nm+(job?' from job '+job:'')+'. It is not in Equipment and Materials. Add it to the register if we are keeping it in stock.',link:H+'cbs-admin?open=kit'});
    return [{json:{ok:true,kind:'matreturn',message:f3(q)+(un?' '+un:'')+' '+nm+' logged as back in the yard. The office has been asked to add it to the register.'}}];
  }
  const R=await this.helpers.httpRequest({method:'GET',url:H+'cbs-admin-data?t=materials',json:true,timeout:30000});
  const m=(R.materials||[]).find(x=>String(x.id)===S(b.id));
  if(!m) return [{json:{ok:false,kind:'err',message:'That material was not found. Refresh and try again.'}}];
  const nq=num(m.qty_on_hand)+q;
  await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=materials&id='+m.id+'&partial=1',body:{qty_on_hand:f3(nq)},json:true,timeout:20000});
  await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=stockmoves',body:{material_id:String(m.id),material:S(m.name),change:f3(q),qty_after:f3(nq),reason:'Returned from job',ref:job?'Job '+job:'Yard return',by:by,at:now,notes:'',location:S(m.location)},json:true,timeout:20000});
  return [{json:{ok:true,kind:'matreturn',message:f3(q)+' '+S(m.unit)+' '+S(m.name)+' back in stock (now '+f3(nq)+').'}}];
}
if(b.action==='loadissue'){
  const R=await this.helpers.httpRequest({method:'GET',url:H+'cbs-admin-data?t=ptmsheets,notices',json:true,timeout:30000});
  const s=(R.ptmsheets||[]).find(x=>String(x.id)===S(b.id));
  if(!s) return [{json:{ok:false,kind:'err',message:'That load-up sheet was not found.'}}];
  const RS={out:'Out of stock',faulty:'Faulty',missing:"Can't find it",nobuy:"Couldn't buy it"};
  const items=(Array.isArray(b.items)?b.items:[]).slice(0,100).map(i=>({name:S(i.name).slice(0,120),detail:S(i.detail).slice(0,60),reason:S(i.reason),note:S(i.note).slice(0,300)})).filter(i=>i.name&&RS[i.reason]);
  const gen=S(b.note).slice(0,500);
  if(!items.length&&!gen) return [{json:{ok:true,kind:'loadissue',message:'Nothing to report.'}}];
  /* quantities only (e.g. 2 of 6 bags); plant categories are left out */
  const nm=i=>i.name+(/[0-9]/.test(i.detail)?' ('+i.detail.replace(/^buy on the way,?\s*/i,'')+')':'')+(i.note?' - '+i.note:'');
  const groups=[];Object.keys(RS).forEach(k=>{const L=items.filter(i=>i.reason===k);if(L.length)groups.push(RS[k]+': '+L.map(nm).join(', '));});
  const n=items.length,job=S(s.job_no),where=job?'Job '+job:'Load-up #'+s.id;
  const title=where+' load-up: '+(n?n+' item'+(n===1?'':'s')+(b.loaded?' not loaded':' with a problem'):'problem reported')+'.';
  const body=[[S(s.site),'Load-up #'+s.id,by+', '+stamp.slice(0,5)+' '+stamp.slice(11)].filter(Boolean).join(' \u00b7 ')].concat(groups).concat(gen?['Note: '+gen]:[]).concat(['Find them or arrange replacements, then mark this done.']);
  const rec=stamp+' '+by+(b.loaded?' (when loading)':'')+': '+groups.concat(gen?['Note: '+gen]:[]).join('; ');
  await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=ptmsheets&id='+s.id+'&partial=1',body:{load_issues:(S(s.load_issues)?S(s.load_issues)+NL:'')+rec},json:true,timeout:20000});
  /* one open card per sheet: older open problem cards for this sheet are closed. The card opens the sign-out sheet (everything in one place). */
  const link=H+'cbs-ptm-crew?id='+s.id,oldLink=H+'cbs-ptm-sheet?id='+s.id;
  for(const o of (R.notices||[]).filter(x=>S(x.event)==='ptm_short'&&(S(x.link)===link||S(x.link)===oldLink)&&S(x.status)!=='Done')){try{await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=notices&id='+o.id+'&partial=1&k='+K,body:{status:'Done',notes:[S(o.notes),'Replaced by a newer report '+stamp].filter(Boolean).join(NL)},json:true,timeout:15000});}catch(e){}}
