  const M={};(R.materials||[]).forEach(m=>{M[String(m.id)]=m;});
  const lines=[];let diff=0;
  (Array.isArray(b.lines)?b.lines:[]).slice(0,500).forEach(l=>{const m=M[S(l.id)];if(!m)return;const c=num(l.counted);if(c<0)return;const sys=num(m.qty_on_hand);if(Math.abs(c-sys)>1e-9)diff++;
    lines.push({id:String(m.id),name:S(m.name),unit:S(m.unit),location:S(m.location),system:f3(sys),counted:f3(c)});});
