const b=$('Approve Hook').first().json.body||{};
const S=v=>v==null?'':String(v).trim();
const num=v=>{const n=parseFloat(String(v==null?'':v).replace(/[^0-9.-]/g,''));return isNaN(n)?0:n;};
const f3=n=>String(Math.round(n*1000)/1000);
const H='https://old-hub.example/webhook/';
const st=$input.all().map(i=>i.json).find(r=>r&&Number(r.id)===Number(b.id));
if(!st) return [{json:{ok:false,message:'Stock take not found.'}}];
if(st.status!=='Pending') return [{json:{ok:false,message:'Stock take #'+st.id+' has already been '+String(st.status).toLowerCase()+'.'}}];
const by=S(b.by);if(!by) return [{json:{ok:false,message:'Choose your name.'}}];
const now=new Date().toLocaleString('sv-SE',{timeZone:'Europe/London'}).replace(' ','T').slice(0,16);
let L=[];try{L=JSON.parse(st.lines_json||'[]');}catch(e){}
const notes=S(b.notes).slice(0,500);
if(b.action==='reject'){
  return [{json:{ok:true,id:st.id,upd:{status:'Rejected',decided_by:by,decided_at:now,notes:notes},message:'Stock take #'+st.id+' rejected. Stock has not changed.'}}];
}
if(b.action!=='approve') return [{json:{ok:false,message:'Unknown action.'}}];
const edits={};(Array.isArray(b.lines)?b.lines:[]).forEach(l=>{edits[S(l.id)]=num(l.counted);});
const R=await this.helpers.httpRequest({method:'GET',url:H+'cbs-admin-data?t=materials',json:true,timeout:30000});
const M={};(R.materials||[]).forEach(m=>{M[String(m.id)]=m;});
let changed=0;
for(const l of L){
  const m=M[String(l.id)];if(!m)continue;
  if(edits[String(l.id)]!==undefined)l.counted=f3(edits[String(l.id)]);
  const counted=num(l.counted),sys=num(l.system),cur=num(m.qty_on_hand);
  /* keep anything used or received since the count: new = counted + (stock now - stock at count) */
  const nq=Math.max(0,counted+(cur-sys)),delta=nq-cur;
  const ch={last_counted_on:now.slice(0,10),last_counted_by:S(st.counted_by)};
  if(Math.abs(delta)>1e-9){ch.qty_on_hand=f3(nq);changed++;
    await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=stockmoves',body:{material_id:String(m.id),material:S(m.name),change:f3(delta),qty_after:f3(nq),reason:'Stock take adjustment',ref:'Stock take #'+st.id,by:by,at:now,notes:'Counted '+f3(counted)+' by '+S(st.counted_by)+' (system '+f3(sys)+')',location:S(m.location)},json:true,timeout:20000});}
  await this.helpers.httpRequest({method:'POST',url:H+'cbs-admin-save?a=save&t=materials&id='+m.id+'&partial=1',body:ch,json:true,timeout:20000});
}
return [{json:{ok:true,id:st.id,upd:{status:'Approved',decided_by:by,decided_at:now,notes:notes,lines_json:JSON.stringify(L)},message:'Stock take #'+st.id+' approved. '+changed+' stock level'+(changed===1?'':'s')+' updated.'}}];

